const ELEMENT_PROP_KEYS = new Set(["theme","metric","label","fontWeight","flight","accent","fontFamily","ink","background","scale","delay","grain","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  metric: "3×",
  label: "faster growth",
  fontWeight: 400,
  flight: 32,
  accent: "#3B5BFD",
  fontFamily: "Space Grotesk",
  scale: 1,
  delay: 0,
  grain: true,
  speed: 1,
};

type FlowArrowElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof FlowArrowBase>;

const FlowArrowInner = forwardRef<
  HTMLDivElement,
  FlowArrowElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<FlowArrow>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <FlowArrowBase
          {...(componentProps as unknown as ComponentProps<typeof FlowArrowBase>)}
        />
      </div>
    </Sequence>
  );
});

export const FlowArrow = Interactive.withSchema({
  Component: FlowArrowInner,
  componentName: "<FlowArrow>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
